INSERT INTO `cms_homes_stickers` VALUES ('3991', '1271', '68', '639', '33', '[b][color=yellow]Joker:[/color][/b] [color=red]Zorgt dat iedereen zijn \r\ntegels in jouw kleur markeert[/color]', '3', '0', 'nakedskin', '344', null);
