INSERT INTO `cms_homes_stickers` VALUES ('3993', '1271', '68', '702', '35', '[b][color=yellow]Willekeurig:[/color][/b] [color=red]Geeft je een willekeurige power-up![/color]', '3', '0', 'nakedskin', '344', null);
INSERT INTO `cms_homes_stickers` VALUES ('3994', '1271', '662', '211', '37', '[b][size=large]Tips &amp; Tactieken[/size][/b]\r\n\r\n[b]Tip 1:[/b] Het stuiteren over de tegels van je tegenstander geeft je meer punten dan het stuiteren over lege vakjes. \r\n\r\n[b]Tip 2:[/b] Stuiter meerdere keren op je eigen tegels om extra punten te verdienen!', '3', '0', 'nakedskin', '344', null);
INSERT INTO `cms_homes_stickers` VALUES ('3995', '1271', '648', '530', '41', '[b]Tip 4:[/b] De beste power-up om te pakken is de Joker, terwijl de slechtste power-up om te pakken het Doosje Punaises is.\r\n\r\n\r\n[b]Tip 5:[/b] Door drie keer op je tegels te \r\nstuiteren vul je alle tegels die je ingesloten \r\nhebt!', '3', '0', 'nakedskin', '344', null);
INSERT INTO `cms_homes_stickers` VALUES ('3997', '1271', '31', '992', '42', '[color=yellow][b]BattleBall: Rebound kost niets! \r\n\r\nDe punten die je bij elkaar stuitert worden opgeteld bij je totale score voor SnowStorm en BattleBall. \r\n\r\nCheck de Games-homepage voor de beste spelers van het moment![/b][/color]', '3', '0', 'nakedskin', '344', null);
INSERT INTO `cms_homes_stickers` VALUES ('3998', '1271', '0', '1151', '44', '[color=yellow]Je kunt nu vanuit elke kamer in \r\nhet hotel een nieuwe game starten \r\nof meedoen met een door andere \r\ngemaakte game. Klik daarvoor op \r\nde joystick onderin je Habboscherm.[/color]', '3', '0', 'nakedskin', '344', null);
INSERT INTO `cms_homes_stickers` VALUES ('3999', '1271', '72', '792', '46', '[color=yellow][size=large][b]Game Starten?[/b][/size][/color]', '3', '0', 'nakedskin', '344', null);
