-- ----------------------------
-- Table structure for games_ranks
-- ----------------------------
DROP TABLE IF EXISTS `games_ranks`;
CREATE TABLE `games_ranks` (
  `id` int(5) NOT NULL auto_increment,
  `type` enum('ss','bb') collate latin1_general_ci NOT NULL default 'bb',
